const LanguageContext = createContext()

export const useTranslation = () => {
  const context = useContext(LanguageContext)
  if (!context) {
    throw new Error('useTranslation must be used within a LanguageProvider')
  }
  return context
}

export const LanguageProvider = ({ children }) => {
  // Язык живёт в URL: /ru/... и /en/... — единственный источник правды.
  // Всё, что не начинается с /en, считается языком по умолчанию.
  const location = useLocation()
  const navigate = useNavigate()
  const language = getLanguageFromPath(location.pathname)

  const t = (key) => {
    const keys = key.split('.')
    let value = translations[language]
    
    for (const k of keys) {
      value = value?.[k]
    }
    
    return value || key
  }

  // <html lang> должен совпадать с текущим языком сайта — и при первой загрузке,
  // и при каждом переключении. Атрибут меняем в эффекте, чтобы не трогать DOM
  // во время рендера и не вызывать лишних перерисовок.
  useEffect(() => {
    document.documentElement.lang = language
  }, [language])

  // Переключатель остаётся на той же странице: меняется только языковой префикс,
  // slug, query и hash сохраняются.
  const toggleLanguage = () => {
    const newLanguage = language === 'ru' ? 'en' : 'ru'
    const target = localizedPath(
      newLanguage,
      `${location.pathname}${location.search}${location.hash}`
    )

    navigate(target, { replace: true })
  }

  return (
    <LanguageContext.Provider value={{ language, t, toggleLanguage }}>
      {children}
    </LanguageContext.Provider>
  )
}
